export function createForceObstacle(descriptor: ForceObstacle): BallObstacle {
  const zone = descriptorZone(descriptor);
  if (descriptor.type === 'teleporter') {
    return new TeleporterObstacle({
      id: descriptor.id,
      kind: 'teleporter',
      enabled: descriptor.enabled,
      entryZone: zone,
      exitPosition: { ...descriptor.exit },
      exitVelocityScale: descriptor.exitVelocityScale,
      clearAngularVelocity: descriptor.clearAngularVelocity,
    });
  }

  const direction = normalizeVec3(descriptor.direction) ?? FORWARD;
  if (descriptor.type === 'fan') {
    return new FanObstacle({
      id: descriptor.id,
      kind: 'fan',
      enabled: descriptor.enabled,
      zone,
      direction,
      maxForce: descriptor.strength,
      falloff: descriptor.falloff,
      pulse: descriptor.pulse,
    });
  }

  return new ConveyorObstacle({
    id: descriptor.id,
    kind: 'conveyor',
    enabled: descriptor.enabled,
    zone,
    direction,
    targetSpeed: descriptor.strength,
    coupling: descriptor.coupling,
  });
}

export function createPad(descriptor: PadDescriptor): PadObstacle {
  return new PadObstacle({
    id: descriptor.id,
    kind: PAD_KINDS[descriptor.type],
    zone: descriptorZone(descriptor),
    strength: descriptor.strength,
    direction: descriptor.direction,
    maxSpeed: descriptor.maxSpeed,
    cooldownSeconds: descriptor.cooldownSeconds,
    enabled: descriptor.enabled,
  });
}

/** Static bumpers double as impulse pads; their restitution drives the bounce strength. */
export function createBumperPad(descriptor: StaticObstacle): PadObstacle | null {
  if (descriptor.type !== 'bumper') return null;
  return new PadObstacle({
    id: descriptor.id,
    kind: 'bumper',
    zone: descriptorZone(descriptor),
    strength: descriptor.restitution ?? 1,
    enabled: descriptor.enabled,
  });
}

export function createZone(descriptor: FieldObstacle | HazardObstacle): IZone {
  const bounds = descriptorBounds(descriptor);
  switch (descriptor.type) {
    case 'water':
      return new WaterZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
    case 'lava':
      return new LavaZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 2, descriptor.resetPosition);
    case 'void':
    case 'reset-zone':
      return new KillZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
    case 'gravity-zone':
      return new GravityZone(descriptor.id, bounds, descriptor.strength, descriptor.direction ?? DOWN);
    case 'magnet-zone':
      return new MagnetZone(descriptor.id, bounds, descriptor.strength, descriptor.repel ?? false);
  }
}

export function createRotatingConfig(descriptor: MovingObstacle): RotatingConfig | null {
  const kind = ROTATING_KINDS[descriptor.type];
  if (!kind || descriptor.motion.kind === 'translate') return null;
  const motion = descriptor.motion;
  return {
    id: descriptor.id,
    kind,
    center: { ...descriptor.transform.position },
    armLength: motion.armLength ?? Math.max(descriptor.size.x, descriptor.size.z) / 2,
    speed: motion.speed,
    phase: motion.phase,
    clockwise: motion.clockwise,
    swingAngle: motion.swingAngle,
    enabled: descriptor.enabled,
  };
}

export function createMoverConfig(descriptor: MovingObstacle): MoverConfig | null {
  const kind = MOVER_KINDS[descriptor.type];
  if (!kind || descriptor.motion.kind !== 'translate') return null;
  const motion = descriptor.motion;
  return {
    id: descriptor.id,
    kind,
    origin: { ...descriptor.transform.position },
    axis: { ...motion.axis },
    distance: motion.distance ?? 0,
    speed: Math.abs(motion.speed),
    phase: motion.phase,
    loop: motion.loop,
    pauseSeconds: motion.pauseSeconds,
    enabled: descriptor.enabled,
  };
}

export interface HoleObstacleRuntime {
  forces: BallObstacle[];
  pads: PadObstacle[];
  zones: IZone[];
  rotating: RotatingConfig[];
  movers: MoverConfig[];
}

/** Instantiates every runtime helper a hole descriptor asks for, grouped by system. */
export function buildHoleObstacleRuntime(hole: Hole): HoleObstacleRuntime {
  const runtime: HoleObstacleRuntime = { forces: [], pads: [], zones: [], rotating: [], movers: [] };

  for (const obstacle of hole.obstacles) {
    if (isForceObstacle(obstacle)) {
      runtime.forces.push(createForceObstacle(obstacle));
    } else if (isPadDescriptor(obstacle)) {
      runtime.pads.push(createPad(obstacle));
    } else if (isFieldObstacle(obstacle) || isHazardObstacle(obstacle)) {
      runtime.zones.push(createZone(obstacle));
    } else if (isMovingObstacle(obstacle)) {
      const rotating = createRotatingConfig(obstacle);
      if (rotating) runtime.rotating.push(rotating);
      const mover = createMoverConfig(obstacle);
      if (mover) runtime.movers.push(mover);
    } else {
      const bumper = createBumperPad(obstacle);
      if (bumper) runtime.pads.push(bumper);
    }
  }

  return runtime;
}
